package com.campusiq.platform.controller; import com.campusiq.platform.dto.*; import com.campusiq.platform.entity.Platform; import com.campusiq.platform.service.PlatformService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/platforms") public class PlatformController {private final PlatformService service; public PlatformController(PlatformService s){service=s;} @PostMapping public PlatformProfileResponse connect(@AuthenticationPrincipal Long userId,@Valid @RequestBody ConnectPlatformRequest r){return service.connect(userId,r);}@GetMapping public List<PlatformAccountResponse> all(@AuthenticationPrincipal Long userId){return service.accounts(userId);}@GetMapping("/{platform}") public PlatformProfileResponse one(@AuthenticationPrincipal Long userId,@PathVariable Platform platform){return service.storedProfile(userId,platform);}@PostMapping("/{platform}/sync") public PlatformProfileResponse sync(@AuthenticationPrincipal Long userId,@PathVariable Platform platform){return service.sync(userId,platform);}}
